import { describe, expect, test } from "bun:test";
import vectors from "./vectors/smc-vectors.v1.json";
import { analyzeSmc, smcContext, type SmcResult } from "./smc";

/**
 * Golden vectors: every case in smc-vectors.v1.json is generated by the Python reference
 * (python/jev_analytics/smc.py) and must be reproduced exactly: integers and words equal, prices within the
 * file tolerance. The hand cases below are worked out on paper and do not depend on the reference at all.
 */

const TOL = vectors.tolerance;

function expectSame(got: unknown, want: unknown, path: string): void {
  if (typeof want === "number") {
    expect(typeof got, `${path}: expected a number`).toBe("number");
    const diff = Math.abs((got as number) - want);
    expect(diff <= TOL.abs + TOL.rel * Math.abs(want), `${path}: |${got} - ${want}| = ${diff}`).toBe(true);
    return;
  }
  if (Array.isArray(want)) {
    expect(Array.isArray(got), `${path}: expected an array`).toBe(true);
    expect((got as unknown[]).length, `${path}: length`).toBe(want.length);
    want.forEach((item, i) => expectSame((got as unknown[])[i], item, `${path}[${i}]`));
    return;
  }
  if (want !== null && typeof want === "object") {
    expect(got !== null && typeof got === "object", `${path}: expected an object`).toBe(true);
    expect(Object.keys(got as object).sort(), `${path}: keys`).toEqual(Object.keys(want).sort());
    for (const key of Object.keys(want)) expectSame((got as Record<string, unknown>)[key], (want as Record<string, unknown>)[key], `${path}.${key}`);
    return;
  }
  expect(got, path).toBe(want);
}

type Series = { open: number[]; high: number[]; low: number[]; close: number[] };
const SERIES = vectors.series as unknown as Record<string, Series>;

function run(key: string, n: number, price?: number): SmcResult {
  const s = SERIES[key]!;
  return analyzeSmc(s.open, s.high, s.low, s.close, n, price);
}

describe("smart money golden vectors", () => {
  test("the file is the synthetic fixture the generator labels it as", () => {
    expect(vectors.origin).toBe("synthetic_fixture");
    expect(vectors.cases.length).toBeGreaterThan(20);
  });

  for (const c of vectors.cases) {
    test(`case ${c.name}`, () => {
      const got = run(c.series, c.n, c.price ?? undefined);
      expectSame(got, c.expected, c.name);
    });
  }
});

describe("hand worked cases", () => {
  test("pivots confirmed n bars later, BOS while the direction holds, CHoCH on the flip, one supply block", () => {
    const r = run("hand_structure", 1);
    expect(r.swings.map((s) => [s.kind, s.index, s.price, s.confirmedAt])).toEqual([["high", 1, 12.5, 2], ["high", 3, 13.5, 4], ["high", 5, 15.5, 6], ["low", 8, 10.5, 9], ["low", 10, 8.5, 11]]);
    expect(r.events.map((e) => [e.type, e.dir, e.index, e.level, e.swingIndex])).toEqual([["BOS", "up", 3, 12.5, 1], ["BOS", "up", 5, 13.5, 3], ["CHoCH", "down", 10, 10.5, 8]]);
    expect(r.trend).toBe("down");
    expect(r.orderBlocks).toEqual([{ index: 5, dir: "down", low: 11.5, high: 15.5, formedAt: 10, mitigatedAt: null }]);
    expect(r.range).toEqual({ low: 8.5, high: 15.5, lowIndex: 10, highIndex: 5 });
    expect(r.position).toBeCloseTo((10 - 8.5) / 7, 12);
  });

  test("a close through the block mitigates it and a CHoCH up leaves a demand block", () => {
    const r = run("hand_structure_flip", 1);
    expect(r.orderBlocks.find((b) => b.dir === "down")?.mitigatedAt).toBe(12);
    expect(r.events[r.events.length - 1]).toEqual({ index: 12, type: "CHoCH", dir: "up", level: 15.5, swingIndex: 5 });
    expect(r.orderBlocks.find((b) => b.dir === "up")).toEqual({ index: 10, dir: "up", low: 8.5, high: 12.5, formedAt: 12, mitigatedAt: null });
  });

  test("price outside the swing range is clamped and named", () => {
    expect([run("hand_structure", 1, 20).position, run("hand_structure", 1, 20).rangeState]).toEqual([1, "above"]);
    expect([run("hand_structure", 1, 1).position, run("hand_structure", 1, 1).rangeState]).toEqual([0, "below"]);
  });

  test("a bullish gap is open with a partial fill, then filled when the low reaches its far edge", () => {
    const open = run("hand_gap_open", 3).fvgs;
    expect(open.length).toBe(1);
    expect(open[0]).toMatchObject({ index: 16, dir: "up", low: 100.5, high: 101.8, filledAt: null });
    expect(open[0]!.fill).toBeCloseTo((101.8 - 101.0) / 1.3, 12);
    expect(run("hand_gap_filled", 3).fvgs[0]).toMatchObject({ fill: 1, filledAt: 18 });
    expect(run("hand_gap_bearish", 3).fvgs[0]).toMatchObject({ index: 16, dir: "down" });
  });

  test("equal highs form one pool; a wick back inside sweeps it, a close above consumes it", () => {
    expect(run("hand_pool_active", 1).pools).toEqual([{ kind: "eqh", price: 100.82, indices: [15, 17], sweptAt: null, takenAt: null }]);
    expect(run("hand_pool_swept", 1).pools[0]).toMatchObject({ sweptAt: 19, takenAt: null });
    expect(run("hand_pool_taken", 1).pools[0]).toMatchObject({ sweptAt: null, takenAt: 19 });
    expect(run("hand_pool_lows", 1).pools[0]).toMatchObject({ kind: "eql", indices: [15, 17] });
  });
});

describe("no repainting and edges", () => {
  test("what is known at bar k never changes when later bars arrive", () => {
    const s = SERIES.walk_202!;
    const full = analyzeSmc(s.open, s.high, s.low, s.close, 3);
    for (const cut of [60, 111, 180, 259]) {
      const part = analyzeSmc(s.open.slice(0, cut), s.high.slice(0, cut), s.low.slice(0, cut), s.close.slice(0, cut), 3);
      expect(part.swings).toEqual(full.swings.filter((x) => x.confirmedAt < cut));
      expect(part.events).toEqual(full.events.filter((x) => x.index < cut));
      const known = (blocks: SmcResult["orderBlocks"]) => blocks.filter((b) => b.formedAt < cut).map((b) => [b.index, b.dir, b.low, b.high, b.formedAt]);
      expect(known(part.orderBlocks)).toEqual(known(full.orderBlocks));
    }
  });

  test("short and empty series have nothing and no position", () => {
    for (const size of [0, 1, 2, 6]) {
      const flat = Array.from({ length: size }, (_, i) => 100 + i);
      const r = analyzeSmc(flat, flat.map((x) => x + 0.5), flat.map((x) => x - 0.5), flat, 3);
      expect([r.swings, r.events, r.orderBlocks, r.fvgs, r.pools, r.range, r.position, r.trend]).toEqual([[], [], [], [], [], null, null, null]);
    }
  });

  test("bad input is refused", () => {
    expect(() => analyzeSmc([1], [1, 2], [1], [1], 3)).toThrow(RangeError);
    expect(() => analyzeSmc([1], [1], [1], [1], 0)).toThrow(RangeError);
    expect(() => analyzeSmc([1], [1], [1], [1], 1.5)).toThrow(RangeError);
  });

  test("the result is plain data that survives JSON", () => {
    const s = SERIES.walk_303!;
    const r = analyzeSmc(s.open, s.high, s.low, s.close, 3);
    expect(JSON.parse(JSON.stringify(r))).toEqual(r);
  });
});

describe("smcContext", () => {
  test("distances are non negative and the counts match the open gaps", () => {
    const s = SERIES.walk_101!;
    const r = analyzeSmc(s.open, s.high, s.low, s.close, 3);
    const last = s.close[s.close.length - 1]!;
    const ctx = smcContext(r, last);
    for (const v of [ctx.demandBlockBps, ctx.supplyBlockBps, ctx.gapNearestBps, ctx.poolAboveBps, ctx.poolBelowBps]) {
      expect(v === null || v >= 0).toBe(true);
    }
    expect(ctx.gapsUp + ctx.gapsDown).toBe(r.fvgs.filter((g) => g.fill < 1).length);
    const e = r.events[r.events.length - 1];
    if (e !== undefined) expect(ctx.lastBreak).toEqual({ kind: e.type, dir: e.dir, ageBars: s.close.length - 1 - e.index });
  });

  test("the distance to a block is zero when the price sits inside the zone", () => {
    const base = { n: 3, bars: 10, trend: null, swings: [], events: [], fvgs: [], pools: [], range: null, position: null, rangeState: null } as const;
    const block = { index: 3, dir: "up", low: 99, high: 101, formedAt: 5, mitigatedAt: null } as const;
    expect(smcContext({ ...base, orderBlocks: [block] }, 100).demandBlockBps).toBe(0);
    expect(smcContext({ ...base, orderBlocks: [block] }, 103).demandBlockBps).toBeCloseTo((2 / 103) * 10_000, 9);
  });

  test("an empty reading is all unknown", () => {
    const ctx = smcContext(analyzeSmc([], [], [], [], 3), 100);
    expect(Object.values(ctx).filter((v) => v !== null && v !== 0)).toEqual([]);
  });
});
